function bgmBeat(){if(!state.running||state.paused||state.ended||!state.settings.music||document.hidden)return;const boss=state.selectedMode==="boss",lead=boss?[110,110,131,147,110,165,147,131]:[220,277,330,277,247,330,370,330],bass=boss?[55,55,65,73]:[110,110,123,98],i=bgmStep++%8;musicTone(lead[i],.2,boss?.032:.022,i%2?"triangle":"square");if(i%2===0)musicTone(bass[(i/2)%4],.42,boss?.038:.025,"sawtooth")}
