function useAbility(){const f=me();if(!f||!f.alive||f.abilityCd>0||state.paused||state.ended)return;const level=skillLevel();f.abilityCd=state.selectedMode==="practice"?2.5:10;if(state.selectedMode==="tutorial"&&state.tutorialStep>=2){state.tutorialTargetKills=matchStats.kills+1;state.tutorialAbility=true;}sfx("ability");vibrate([35,25,60]);if(f.classType==="assault")f.abilityTime=level>=3?6:level>=2?5:3.5;if(f.classType==="tank"){const duration=level>=3?6:level>=2?5:3.5;f.shield=duration;f.inv=duration;if(level>=3)f.hp=Math.min(f.maxHp,f.hp+45)}if(f.classType==="sniper"){f.cool=0;fire(f,true)}if(f.classType==="support"){const radius=level>=3?280:level>=2?235:195,heal=level>=3?70:level>=2?52:36;for(const ally of fighters.filter(x=>x.alive&&x.team===f.team&&d2(x,f)<=radius**2)){ally.hp=Math.min(ally.maxHp,ally.hp+heal);if(level>=3)ally.inv=Math.max(ally.inv,.7)}for(let i=0;i<36;i++){const a=i/36*Math.PI*2;particles.push({x:f.x+Math.cos(a)*radius*.25,y:f.y+Math.sin(a)*radius*.25,vx:Math.cos(a)*radius,vy:Math.sin(a)*radius,life:.65,max:.65,color:"#4ff0a4",size:4})}}for(let i=0;i<28;i++){const a=Math.random()*Math.PI*2;particles.push({x:f.x,y:f.y,vx:Math.cos(a)*(80+Math.random()*180),vy:Math.sin(a)*(80+Math.random()*180),life:.7,max:.7,color:CLASSES[f.classType].color,size:3+Math.random()*5})}}
