function updateModeStatus(){if(!ui.modeStatus)return;ui.bossHud.classList.toggle("visible",state.running&&state.selectedMode==="boss"&&!state.ended);if(state.selectedMode==="classic")ui.modeStatus.textContent="3대3 클래식 · 먼저 10점";else if(state.selectedMode==="domination")ui.modeStatus.textContent=state.dominationContested?`점령전 · 거점 경합 중 · ${Math.floor(state.blue)} : ${Math.floor(state.red)}`:state.dominationOwner==="neutral"?`점령전 · 중앙 거점을 점령하세요 · ${Math.floor(state.blue)} : ${Math.floor(state.red)}`:`점령전 · ${state.dominationOwner.toUpperCase()} 점령 중 · ${Math.floor(state.blue)} : ${Math.floor(state.red)}`;else if(state.selectedMode==="wave")ui.modeStatus.textContent=state.waveWaiting?`웨이브 ${state.wave} 완료 · 다음 공격 준비`:`생존 웨이브 ${state.wave}/5 · 남은 적 ${fighters.filter(f=>f.team==="red"&&f.alive).length}`;else if(state.selectedMode==="tutorial")ui.modeStatus.textContent=`튜토리얼 · ${Math.min(4,state.tutorialStep+1)}/4 단계`;else if(state.selectedMode==="practice")ui.modeStatus.textContent=`연습장 · 표적 처치 ${matchStats.kills}`;else{const boss=fighters.find(f=>f.boss);ui.modeStatus.textContent=boss?.bossWarning?`⚠ ${boss.bossWarning.type==="ring"?"원형 탄막":boss.bossWarning.type==="aim"?"조준 공격":"돌진"} 준비!`:`보스전 · 지원 로봇 ${fighters.filter(f=>f.id?.startsWith("guardian-drone")&&f.alive).length}기`;ui.bossFill.style.width=`${boss?Math.max(0,boss.hp/boss.maxHp*100):0}%`;ui.bossPhase.textContent=`PHASE ${boss?.phase||1}`} }
function hud(){ui.bs.textContent=Math.floor(state.blue);ui.rs.textContent=Math.floor(state.red);ui.mapLabel.textContent=MAPS[state.selectedMap].label;const s=Math.ceil(state.time);ui.timer.textContent=state.selectedMode==="tutorial"||state.selectedMode==="practice"?"∞":`${String(Math.floor(s/60)).padStart(2,"0")}:${String(s%60).padStart(2,"0")}`;const p=me();if(p){const c=CLASSES[p.classType],level=skillLevel(),needed=level===1?3-matchStats.kills:level===2?6-matchStats.kills:0;ui.classLabel.textContent=`${c.label} · HP`;ui.hp.textContent=Math.ceil(p.hp);ui.fill.style.width=`${p.hp/p.maxHp*100}%`;ui.skillProgress.textContent=level===3?"스킬 LV.3 · 최대 강화":`스킬 LV.${level} · 다음 강화까지 ${needed}킬`;ui.abilityName.textContent=`${c.ability} · LV.${level}`;ui.abilityCooldown.style.height=`${Math.min(100,p.abilityCd/(state.selectedMode==="practice"?2.5:10)*100)}%`;ui.ability.classList.toggle("ready",p.abilityCd<=0&&p.alive);ui.ability.disabled=!p.alive;const buffs=[["⚡ 속사",p.haste,"#42d8ff"],["≫ 가속",p.speedBuff,"#ff9b4a"],["◆ 보호막",p.shield,"#9b8cff"],["★ 오버차지",p.overcharge,"#ff62d4"]].filter(x=>x[1]>.05);ui.buffStatus.innerHTML=buffs.map(x=>`<span class="buff-chip" style="--buff:${x[2]}">${x[0]} ${x[1].toFixed(1)}초</span>`).join("");ui.respawn.textContent=p.alive?(p.abilityTime>0?`${c.ability} ${p.abilityTime.toFixed(1)}초`:p.shield>0?`보호막 ${p.shield.toFixed(1)}초`:""):`복귀까지 ${Math.max(0,p.respawn).toFixed(1)}초`}updateModeStatus();renderMapEventHud()}
function finish(w){if(state.ended)return;state.ended=true;const limit=state.selectedMode==="wave"?180:state.selectedMode==="boss"||state.selectedMode==="domination"?150:120,elapsed=Math.max(0,limit-state.time),isNew=state.selectedMode==="classic"&&w==="blue"&&(state.bestTime===null||elapsed<state.bestTime),accuracy=matchStats.shots?Math.round(matchStats.hits/matchStats.shots*100):0;if(isNew){state.bestTime=elapsed;saveBestTime(state.bestTime)}ui.best.textContent=formatBestTime(state.bestTime);ui.statTime.textContent=state.selectedMode==="tutorial"?"훈련 완료":`${elapsed.toFixed(1)}초`;ui.statKills.textContent=matchStats.kills;ui.statDeaths.textContent=matchStats.deaths;ui.statShots.textContent=matchStats.shots;ui.statAccuracy.textContent=`${accuracy}%`;ui.statDamage.textContent=Math.round(matchStats.damage);ui.resultBest.textContent=state.selectedMode==="tutorial"?"🎓 이동·공격·스킬 훈련 완료":state.selectedMode==="wave"?`🌊 도달 웨이브 ${state.wave}/5`:state.selectedMode==="boss"?`👑 보스에게 가한 피해 ${Math.round(matchStats.damage)}`:state.selectedMode==="domination"?`◎ 최종 점령 점수 ${Math.floor(state.blue)} : ${Math.floor(state.red)}`:isNew?`🎉 최단 승리 신기록! ${formatBestTime(state.bestTime)}`:`⚡ 최단 승리 ${formatBestTime(state.bestTime)}`;ui.resultBest.classList.toggle("new-record",isNew);ui.result.classList.add("visible");ui.title.textContent=w==="draw"?"무승부":w==="blue"?(state.selectedMode==="wave"?"생존 성공!":state.selectedMode==="boss"?"보스 격파!":state.selectedMode==="tutorial"?"튜토리얼 완료!":state.selectedMode==="domination"?"BLUE 거점 승리!":"BLUE 승리!"):((state.selectedMode==="classic"||state.selectedMode==="domination")?"RED 승리":"도전 종료");ui.title.style.color=w==="draw"?"#fff":COLOR[w];ui.score.textContent=state.selectedMode==="tutorial"?"기본 조작을 모두 익혔습니다.":(state.selectedMode==="classic"||state.selectedMode==="domination")?`BLUE ${Math.floor(state.blue)} : ${Math.floor(state.red)} RED`:state.selectedMode==="wave"?`총 ${state.blue}명 처치`:`네온 가디언 도전`}
const completeMatch=finish;
function matchReward(w){if(state.rewarded)return{coins:0,xp:0,seasonXp:0,leveled:false};const won=w==="blue",modeBonus=state.selectedMode==="wave"?state.wave*4:state.selectedMode==="boss"&&won?35:0,reward=10+matchStats.kills*4+(won?20:0)+modeBonus,xp=20+matchStats.kills*8+(won?35:0)+(state.selectedMode==="wave"?state.wave*5:state.selectedMode==="boss"&&won?45:0),seasonXp=35+matchStats.kills*6+(won?25:0)+(state.selectedMode==="wave"?state.wave*4:state.selectedMode==="boss"&&won?25:0),before=levelInfo().level,s=state.profile.stats,c=ensureChallenges(),damage=Math.round(matchStats.damage),wavePlay=state.selectedMode==="wave"?1:0;state.rewarded=true;state.profile.coins+=reward;state.profile.xp+=xp;state.profile.season.xp+=seasonXp;s.matches++;s.kills+=matchStats.kills;s.damage+=damage;s.wavePlays+=wavePlay;s.coinsEarned+=reward;if(won)s.wins++;for(const period of [c.daily,c.weekly]){period.stats.matches++;period.stats.kills+=matchStats.kills;period.stats.damage+=damage;period.stats.wavePlays+=wavePlay;if(won)period.stats.wins++}if(state.selectedMode==="wave")s.bestWave=Math.max(s.bestWave,state.wave);if(state.selectedMode==="boss"){s.bossDamage+=damage;if(won)s.bossWins++}const leveled=levelInfo().level>before;saveProfile();renderWallet();return{coins:reward,xp,seasonXp,leveled}}
finish=function(w){if(state.ended)return;stopBgm();if(state.selectedMode==="tutorial"){ui.resultCoins.textContent="🪙 튜토리얼 보상 없음";ui.resultXp.textContent="⭐ 조작 훈련 완료";ui.resultSeasonXp.textContent="🌌 시즌 XP 없음";sfx("win");vibrate([35,25,70]);completeMatch(w);return}const reward=matchReward(w);ui.resultCoins.textContent=`🪙 +${reward.coins} 네온 코인`;ui.resultXp.textContent=`⭐ +${reward.xp} XP${reward.leveled?" · 레벨 업!":""}`;ui.resultSeasonXp.textContent=`🌌 +${reward.seasonXp} 시즌 XP`;sfx(w==="blue"?"win":"lose");vibrate(w==="blue"?[40,35,70,35,90]:[90,45,90]);completeMatch(w)};
function upgradeCost(level){return 40+level*35}
function cosmeticUnlocked(item){return item.seasonTier?state.profile.season.claimed[item.seasonTier]===true:levelInfo().level>=item.level}
function renderProfile(){const p=state.profile,l=levelInfo(),rank=rankName(l.level);ui.profileName.textContent=`${BADGES[p.badge].symbol} ${p.name}`;ui.profileLevel.textContent=`LV.${l.level} · ${rank}`;ui.profileXp.textContent=`${l.current} / ${l.needed} XP`;ui.profileXpFill.style.width=`${l.percent}%`;ui.profileScreenLevel.textContent=`LV.${l.level}`;ui.profileRank.textContent=rank;ui.profileNameInput.value=p.name;ui.profileScreenXp.textContent=`${l.current} / ${l.needed} XP`;ui.profileScreenXpFill.style.width=`${l.percent}%`;ui.profileMatches.textContent=p.stats.matches;ui.profileWins.textContent=p.stats.wins;ui.profileKills.textContent=p.stats.kills;ui.profileBossWins.textContent=p.stats.bossWins;ui.skinList.querySelectorAll("button").forEach(b=>{const item=SKINS[b.dataset.skin],locked=!cosmeticUnlocked(item);b.classList.toggle("selected",p.skin===b.dataset.skin);b.classList.toggle("locked",locked);b.dataset.lock=locked?(item.seasonTier?`시즌 ${item.seasonTier}단계`:`LV.${item.level}`):""});document.querySelectorAll(".profile-emblem").forEach(e=>{e.style.background=`linear-gradient(135deg,${SKINS[p.skin].color},#8a8cff)`;e.style.boxShadow=`0 0 18px ${SKINS[p.skin].color}66`});ui.badgeList.querySelectorAll("button").forEach(b=>{const item=BADGES[b.dataset.badge],locked=!cosmeticUnlocked(item);b.classList.toggle("selected",p.badge===b.dataset.badge);b.classList.toggle("locked",locked);b.dataset.lock=locked?(item.seasonTier?`시즌 ${item.seasonTier}단계`:`LV.${item.level}`):""})}
function openProfile(){ui.start.classList.remove("visible");ui.profileScreen.classList.add("visible");ui.profileMessage.textContent="경기를 플레이하면 경험치를 획득합니다.";renderProfile()}
function closeProfile(){ui.profileScreen.classList.remove("visible");ui.start.classList.add("visible");renderProfile()}
function savePlayerName(){const name=ui.profileNameInput.value.trim().replace(/[<>]/g,"").replace(/\s+/g," ").slice(0,10);if(!name){ui.profileMessage.textContent="닉네임을 한 글자 이상 입력해 주세요.";return}state.profile.name=name;saveProfile();renderProfile();ui.profileMessage.textContent="닉네임을 저장했습니다.";sfx("hit")}
function selectCosmetic(type,key){const items=type==="skin"?SKINS:BADGES,item=items[key];if(!item)return;if(!cosmeticUnlocked(item)){ui.profileMessage.textContent=item.seasonTier?`무료 시즌 ${item.seasonTier}단계 보상을 수령하면 해금됩니다.`:`LV.${item.level}에 해금됩니다.`;sfx("damage");return}state.profile[type]=key;saveProfile();renderProfile();ui.profileMessage.textContent=`${item.label}${type==="skin"?" 스킨":" 배지"}을 장착했습니다.`;sfx("hit")}
function renderWallet(){ui.wallet.textContent=state.profile.coins;ui.shopWallet.textContent=state.profile.coins;if(ui.missionWallet)ui.missionWallet.textContent=state.profile.coins;renderProfile()}
function missionCard(m,value,claimed,claimKey){const progress=Math.min(value,m.goal),done=value>=m.goal;return `<article class="mission-card ${done?"complete":""}"><div class="mission-icon">${m.icon}</div><div class="mission-copy"><strong>${m.title}</strong><small>${m.detail}</small><div class="mission-progress"><i style="width:${progress/m.goal*100}%"></i></div><span>${progress.toLocaleString()} / ${m.goal.toLocaleString()}</span></div><button data-claim="${claimKey}" type="button" ${!done||claimed?"disabled":""}>${claimed?"수령 완료":`+${m.reward} 🪙`}</button></article>`}
function challengeGroup(title,note,cards,open=true){return `<details class="challenge-group" ${open?"open":""}><summary><strong>${title}</strong><small>${note}</small></summary><div class="challenge-items">${cards}</div></details>`}
function renderMissions(){const c=ensureChallenges(),starterDone=MISSIONS.every(m=>state.profile.claimed[m.id]),starter=MISSIONS.map(m=>missionCard(m,state.profile.stats[m.stat],state.profile.claimed[m.id],`beginner:${m.id}`)).join(""),daily=PERIOD_MISSIONS.daily.map(m=>missionCard(m,c.daily.stats[m.stat],c.daily.claimed[m.id],`daily:${m.id}`)).join(""),weekly=PERIOD_MISSIONS.weekly.map(m=>missionCard(m,c.weekly.stats[m.stat],c.weekly.claimed[m.id],`weekly:${m.id}`)).join(""),long=Object.entries(LONG_MISSIONS).map(([key,m])=>{const level=c.longLevels[key];if(level>=m.goals.length)return `<article class="mission-card complete"><div class="mission-icon">${m.icon}</div><div class="mission-copy"><strong>${m.title}</strong><small>모든 단계 완료</small><div class="mission-progress"><i style="width:100%"></i></div><span>최종 단계 달성</span></div><button disabled>완료</button></article>`;return missionCard({...m,detail:`${m.unit} ${m.goals[level]} · ${level+1}/${m.goals.length}단계`,goal:m.goals[level],reward:m.rewards[level]},state.profile.stats[m.stat],false,`long:${key}`)}).join("");ui.missionList.innerHTML=challengeGroup("초보자 미션",starterDone?"모두 완료 · 눌러서 보기":"한 번만 받을 수 있어요",starter,!starterDone)+challengeGroup("일일 미션","매일 새로 시작",daily)+challengeGroup("주간 미션","매주 월요일 새로 시작",weekly)+challengeGroup("장기 미션","완료하면 다음 단계 해금",long);ui.achievementList.innerHTML=ACHIEVEMENTS.map(a=>{const unlocked=a.test(state.profile);return `<article class="achievement-card ${unlocked?"unlocked":""}"><span>${unlocked?a.icon:"🔒"}</span><div><strong>${a.title}</strong><small>${a.detail}</small></div><b>${unlocked?"해금":"미달성"}</b></article>`}).join("");ui.missionList.querySelectorAll("[data-claim]").forEach(button=>button.onclick=()=>claimMission(button.dataset.claim));saveProfile();renderWallet()}
function openMissions(){ui.start.classList.remove("visible");ui.missionScreen.classList.add("visible");renderMissions()}
function closeMissions(){ui.missionScreen.classList.remove("visible");ui.start.classList.add("visible");renderWallet()}
function renderSeason(){const season=state.profile.season,xp=season.xp,earned=SEASON.rewards.filter(r=>xp>=r.xp).length,next=SEASON.rewards.find(r=>xp<r.xp),previous=earned?SEASON.rewards[earned-1].xp:0,end=next?.xp||SEASON.rewards[SEASON.rewards.length-1].xp,percent=next?Math.min(100,(xp-previous)/(end-previous)*100):100;ui.seasonTier.textContent=`${earned} / ${SEASON.rewards.length} 단계`;ui.seasonXp.textContent=`${xp.toLocaleString()} 시즌 XP`;ui.seasonFill.style.width=`${percent}%`;ui.seasonNext.textContent=next?`${next.tier}단계까지 ${next.xp-xp} XP`:`시즌 모든 단계 달성!`;ui.seasonTrack.innerHTML=SEASON.rewards.map(r=>{const ready=xp>=r.xp,claimed=season.claimed[r.tier]===true,icon=r.kind==="coins"?"🪙":r.kind==="xp"?"⭐":r.kind==="skin"?"🎨":"✦";return `<article class="season-reward ${ready?"ready":""} ${claimed?"claimed":""}"><div class="season-tier-number">${r.tier}</div><div class="season-reward-icon">${icon}</div><div><strong>${r.label}</strong><small>${r.xp.toLocaleString()} 시즌 XP</small></div><button data-season-tier="${r.tier}" type="button" ${!ready||claimed?"disabled":""}>${claimed?"수령 완료":ready?"수령":"잠김"}</button></article>`}).join("");ui.seasonTrack.querySelectorAll("[data-season-tier]").forEach(button=>button.onclick=()=>claimSeasonReward(Number(button.dataset.seasonTier)))}
function claimSeasonReward(tier){const reward=SEASON.rewards.find(r=>r.tier===tier),season=state.profile.season;if(!reward||season.claimed[tier]||season.xp<reward.xp)return;season.claimed[tier]=true;if(reward.kind==="coins"){state.profile.coins+=reward.amount;state.profile.stats.coinsEarned+=reward.amount}else if(reward.kind==="xp")state.profile.xp+=reward.amount;saveProfile();renderWallet();renderSeason();ui.seasonMessage.textContent=`${reward.label} 보상을 받았습니다!`;sfx("ability");vibrate([25,20,55])}
function openSeason(){ui.start.classList.remove("visible");ui.seasonScreen.classList.add("visible");ui.seasonMessage.textContent="달성한 단계의 보상을 직접 수령하세요.";renderSeason()}
function closeSeason(){ui.seasonScreen.classList.remove("visible");ui.start.classList.add("visible");renderWallet()}
function claimMission(claimKey){const [kind,id]=claimKey.split(":"),c=ensureChallenges();let mission,value,claimed,setClaim;if(kind==="beginner"){mission=MISSIONS.find(m=>m.id===id);value=mission&&state.profile.stats[mission.stat];claimed=state.profile.claimed[id];setClaim=()=>state.profile.claimed[id]=true}else if(kind==="daily"||kind==="weekly"){mission=PERIOD_MISSIONS[kind].find(m=>m.id===id);value=mission&&c[kind].stats[mission.stat];claimed=c[kind].claimed[id];setClaim=()=>c[kind].claimed[id]=true}else if(kind==="long"){const track=LONG_MISSIONS[id],level=c.longLevels[id];if(track&&level<track.goals.length){mission={stat:track.stat,goal:track.goals[level],reward:track.rewards[level]};value=state.profile.stats[track.stat];claimed=false;setClaim=()=>c.longLevels[id]++}}if(!mission||claimed||value<mission.goal)return;setClaim();state.profile.coins+=mission.reward;state.profile.stats.coinsEarned+=mission.reward;saveProfile();sfx("win");vibrate([25,20,50]);renderMissions()}
function renderShop(){const role=state.shopClass,levels=state.profile.upgrades[role];ui.shopClassName.textContent=`${CLASSES[role].label} 강화`;document.querySelectorAll(".shop-class-card").forEach(card=>card.classList.toggle("selected",card.dataset.class===role));document.querySelectorAll("[data-level]").forEach(el=>{const level=levels[el.dataset.level];el.textContent=`LV.${level}/5`});document.querySelectorAll("[data-upgrade]").forEach(button=>{const level=levels[button.dataset.upgrade];button.textContent=level>=5?"최대 강화":`${upgradeCost(level)} 코인`;button.disabled=level>=5});renderWallet()}
function openUpgradeShop(){ui.start.classList.remove("visible");ui.upgradeScreen.classList.add("visible");ui.shopMessage.textContent="강화 효과는 선택한 역할로 시작할 때 적용됩니다.";renderShop()}
function closeUpgradeShop(){ui.upgradeScreen.classList.remove("visible");ui.start.classList.add("visible");renderWallet()}
function renderBalance(){const icons={assault:"⚡",tank:"🛡️",sniper:"🎯",support:"✚"},max={hp:200,damage:65,speed:320,rate:6};ui.balanceRoleList.innerHTML=Object.entries(CLASSES).map(([key,c])=>{const up=state.profile.upgrades[key],hp=Math.round(c.hp*(1+up.hp*.06)),damage=Math.round(c.damage*(1+up.damage*.06)*10)/10,speed=Math.round(c.speed*(1+up.speed*.03)),rate=Math.round(10/c.rate)/10,level=up.hp+up.damage+up.speed,stats=[["체력",hp,max.hp],["공격력",damage,max.damage],["이동",speed,max.speed],["초당 공격",rate,max.rate]];return `<article class="balance-role-card" style="--role:${c.color}"><header><h4>${icons[key]} ${c.label}</h4><span>강화 합계 LV.${level}</span></header>${stats.map(([label,value,limit])=>`<div class="balance-stat"><span>${label}</span><i><em style="width:${Math.min(100,value/limit*100)}%"></em></i><b>${value}</b></div>`).join("")}<div class="balance-skills"><span><strong>필살기</strong>${c.ability}</span><span><strong>보조능력</strong>${AUXILIARIES[key].label} · ${AUXILIARIES[key].cooldown}초</span></div></article>`}).join("");ui.balanceDifficultyList.innerHTML=Object.entries(DIFFICULTY).map(([key,d])=>`<article class="balance-difficulty-card ${state.settings.difficulty===key?"selected":""}"><strong>${d.label}${state.settings.difficulty===key?" · 현재 선택":""}</strong><span>이동 ${Math.round(d.speed*100)}% · 공격력 ${Math.round(d.damage*100)}%<br>공격 간격 ${Math.round(d.rate*100)}% · 팀 전술 ${Math.round(d.teamwork*100)}%</span></article>`).join("")}
function openBalance(){ui.start.classList.remove("visible");ui.balanceScreen.classList.add("visible");renderBalance()}
function closeBalance(){ui.balanceScreen.classList.remove("visible");ui.start.classList.add("visible")}
function buyUpgrade(stat){const level=state.profile.upgrades[state.shopClass][stat],cost=upgradeCost(level);if(level>=5)return;if(state.profile.coins<cost){ui.shopMessage.textContent=`코인이 ${cost-state.profile.coins}개 부족합니다.`;sfx("lose");return}state.profile.coins-=cost;state.profile.upgrades[state.shopClass][stat]++;saveProfile();sfx("ability");vibrate([25,20,40]);ui.shopMessage.textContent=`${CLASSES[state.shopClass].label} ${stat==="hp"?"체력":stat==="damage"?"공격력":"이동속도"} 강화 완료!`;renderShop()}
function returnToSelection(){stopBgm();state.running=false;state.paused=false;state.ended=false;state.teamPing=null;pointer.down=false;input.fire=false;input.mx=0;input.my=0;ui.pingMenu.classList.remove("visible");ui.pingToast.classList.remove("visible");ui.result.classList.remove("visible");ui.pause.classList.remove("visible");ui.settingsScreen.classList.remove("visible");ui.start.classList.add("visible");ui.trainingGuide.classList.remove("visible");ui.mapEvent.classList.remove("visible");ui.best.textContent=formatBestTime(state.bestTime);renderProfile();document.querySelectorAll(".class-card").forEach(card=>card.classList.toggle("selected",card.dataset.class===state.selectedClass));document.querySelectorAll(".map-card").forEach(card=>card.classList.toggle("selected",card.dataset.map===state.selectedMap));document.querySelectorAll(".mode-card").forEach(card=>card.classList.toggle("selected",card.dataset.mode===state.selectedMode))}
function applyControlSettings(){ui.mobileControls.style.setProperty("--stick-size",`${126*state.settings.stickSize}px`);ui.mobileControls.style.setProperty("--stick-opacity",state.settings.stickOpacity);ui.mobileControls.classList.toggle("left-handed",state.settings.leftHanded)}
function resetControlSettings(){Object.assign(state.settings,{leftHanded:false,stickSize:1,stickOpacity:.75,stickDeadzone:.15,aimSensitivity:1});input.mx=0;input.my=0;input.fire=false;saveSettings();renderSettings();sfx("click")}
function renderSettings(){document.querySelectorAll("#difficulty-options button").forEach(button=>button.classList.toggle("selected",button.dataset.value===state.settings.difficulty));ui.shakeToggle.textContent=state.settings.shake?"켜짐":"꺼짐";ui.shakeToggle.classList.toggle("selected",state.settings.shake);ui.soundToggle.textContent=state.settings.sound?"켜짐":"꺼짐";ui.soundToggle.classList.toggle("selected",state.settings.sound);ui.musicToggle.textContent=state.settings.music?"켜짐":"꺼짐";ui.musicToggle.classList.toggle("selected",state.settings.music);ui.musicVolume.value=Math.round(state.settings.musicVolume*100);ui.musicVolumeValue.textContent=`${Math.round(state.settings.musicVolume*100)}%`;ui.vibrationToggle.textContent=state.settings.vibration?"켜짐":"꺼짐";ui.vibrationToggle.classList.toggle("selected",state.settings.vibration);ui.leftHandedToggle.textContent=state.settings.leftHanded?"켜짐":"꺼짐";ui.leftHandedToggle.classList.toggle("selected",state.settings.leftHanded);ui.stickSize.value=Math.round(state.settings.stickSize*100);ui.stickSizeValue.textContent=`${Math.round(state.settings.stickSize*100)}%`;ui.stickOpacity.value=Math.round(state.settings.stickOpacity*100);ui.stickOpacityValue.textContent=`${Math.round(state.settings.stickOpacity*100)}%`;ui.stickDeadzone.value=Math.round(state.settings.stickDeadzone*100);ui.stickDeadzoneValue.textContent=`${Math.round(state.settings.stickDeadzone*100)}%`;ui.aimSensitivity.value=Math.round(state.settings.aimSensitivity*100);ui.aimSensitivityValue.textContent=`${Math.round(state.settings.aimSensitivity*100)}%`;applyControlSettings()}
function openSettings(from){state.settingsFrom=from;ui.start.classList.remove("visible");ui.pause.classList.remove("visible");ui.settingsScreen.classList.add("visible");renderSettings()}
function closeSettings(){ui.settingsScreen.classList.remove("visible");(state.settingsFrom==="pause"?ui.pause:ui.start).classList.add("visible");if(state.settingsFrom==="pause")state.last=performance.now()}
function updateSetting(key,value){state.settings[key]=value;if(key==="shake"&&!value)state.shake=0;if(key==="music"){if(value&&state.running&&!state.paused&&!state.ended)startBgm();else stopBgm()}saveSettings();renderSettings();if(key==="sound"&&value){resumeAudio();sfx("click")}}
function pause(v){if(!state.running||state.ended)return;state.paused=v;ui.pause.classList.toggle("visible",v);if(v){ui.pingMenu.classList.remove("visible");stopBgm()}else{state.last=performance.now();startBgm()}}
function togglePingMenu(){if(!state.running||state.paused||state.ended)return;ui.pingMenu.classList.toggle("visible")}
function updateAuxiliaryHud(){const f=me(),aux=f&&AUXILIARIES[f.classType];if(!aux)return;const total=state.selectedMode==="practice"?2.5:aux.cooldown,left=Math.max(0,((f.auxReadyAt||0)-performance.now())/1000);ui.auxiliaryIcon.textContent=aux.icon;ui.auxiliaryName.textContent=left>0?`${aux.label} ${left.toFixed(1)}`:aux.label;ui.auxiliaryCooldown.style.height=`${Math.min(100,left/total*100)}%`;ui.auxiliary.disabled=!f.alive||state.paused||state.ended||left>0;ui.auxiliary.classList.toggle("ready",f.alive&&!state.paused&&!state.ended&&left<=0)}
function frame(now){const dt=Math.min(.033,(now-state.last)/1000||0);state.last=now;update(dt);draw(camera());updateAuxiliaryHud();requestAnimationFrame(frame)}
function stick(id,type){const el=$(id),knob=el.querySelector(".knob");let active=null;const drag=e=>{if(e.pointerId!==active)return;const r=el.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,max=r.width*.34,d=Math.hypot(dx,dy)||1,m=Math.min(max,d),x=dx/d*m,y=dy/d*m;knob.style.transform=`translate(calc(-50% + ${x}px),calc(-50% + ${y}px))`;const raw=Math.min(1,d/max),dead=state.settings.stickDeadzone,strength=raw<=dead?0:(raw-dead)/(1-dead),vx=dx/d*strength,vy=dy/d*strength;if(type==="move"){input.mx=vx;input.my=vy}else{input.ax=vx;input.ay=vy;input.fire=raw>dead}};const end=e=>{if(e.pointerId!==active)return;active=null;knob.style.transform="translate(-50%,-50%)";if(type==="move"){input.mx=0;input.my=0}else input.fire=false};el.addEventListener("pointerdown",e=>{active=e.pointerId;el.setPointerCapture(active);drag(e)});el.addEventListener("pointermove",drag);el.addEventListener("pointerup",end);el.addEventListener("pointercancel",end)}
addEventListener("resize",resize);
addEventListener("keydown",e=>{keys.add(e.code);if(["Space","ArrowUp","ArrowDown","ArrowLeft","ArrowRight"].includes(e.code))e.preventDefault();if(e.code==="KeyP"&&!ui.settingsScreen.classList.contains("visible"))pause(!state.paused);if(e.code==="KeyE")useAbility();if(e.code==="KeyR")useAuxiliary();if(e.code==="KeyQ"&&!e.repeat)togglePingMenu()});
addEventListener("keyup",e=>keys.delete(e.code));
canvas.addEventListener("pointermove",e=>{pointer.x=e.clientX/viewport.zoom;pointer.y=e.clientY/viewport.zoom;pointer.seen=true});
canvas.addEventListener("pointerdown",e=>{if(e.button===0)pointer.down=true});
addEventListener("pointerup",()=>pointer.down=false);
canvas.addEventListener("contextmenu",e=>e.preventDefault());
document.querySelectorAll(".class-card").forEach(card=>card.onclick=()=>{document.querySelectorAll(".class-card").forEach(x=>x.classList.remove("selected"));card.classList.add("selected");state.selectedClass=card.dataset.class});
document.querySelectorAll(".map-card").forEach(card=>card.onclick=()=>{document.querySelectorAll(".map-card").forEach(x=>x.classList.remove("selected"));card.classList.add("selected");state.selectedMap=card.dataset.map;ui.mapLabel.textContent=MAPS[state.selectedMap].label});
document.querySelectorAll(".mode-card").forEach(card=>card.onclick=()=>{document.querySelectorAll(".mode-card").forEach(x=>x.classList.remove("selected"));card.classList.add("selected");state.selectedMode=card.dataset.mode;updateModeStatus()});
document.querySelectorAll(".shop-class-card").forEach(card=>card.onclick=()=>{state.shopClass=card.dataset.class;ui.shopMessage.textContent="강화 효과는 선택한 역할로 시작할 때 적용됩니다.";renderShop()});
document.querySelectorAll("[data-upgrade]").forEach(button=>button.onclick=()=>buyUpgrade(button.dataset.upgrade));
document.querySelectorAll("#difficulty-options button").forEach(button=>button.onclick=()=>updateSetting("difficulty",button.dataset.value));
$("#shake-toggle").onclick=()=>updateSetting("shake",!state.settings.shake);
$("#sound-toggle").onclick=()=>updateSetting("sound",!state.settings.sound);
$("#music-toggle").onclick=()=>updateSetting("music",!state.settings.music);
ui.musicVolume.oninput=()=>updateSetting("musicVolume",Number(ui.musicVolume.value)/100);
$("#vibration-toggle").onclick=()=>updateSetting("vibration",!state.settings.vibration);
ui.leftHandedToggle.onclick=()=>updateSetting("leftHanded",!state.settings.leftHanded);
ui.stickSize.oninput=()=>updateSetting("stickSize",Number(ui.stickSize.value)/100);
ui.stickOpacity.oninput=()=>updateSetting("stickOpacity",Number(ui.stickOpacity.value)/100);
ui.stickDeadzone.oninput=()=>updateSetting("stickDeadzone",Number(ui.stickDeadzone.value)/100);
ui.aimSensitivity.oninput=()=>updateSetting("aimSensitivity",Number(ui.aimSensitivity.value)/100);
$("#controls-reset-button").onclick=resetControlSettings;
$("#start-settings-button").onclick=()=>openSettings("start");
ui.skinList.querySelectorAll("button").forEach(b=>b.onclick=()=>selectCosmetic("skin",b.dataset.skin));ui.badgeList.querySelectorAll("button").forEach(b=>b.onclick=()=>selectCosmetic("badge",b.dataset.badge));$("#profile-card").onclick=openProfile;
$("#profile-save-button").onclick=savePlayerName;
$("#profile-back-button").onclick=closeProfile;
ui.profileNameInput.addEventListener("keydown",e=>{if(e.key==="Enter")savePlayerName()});
$("#mission-button").onclick=openMissions;
$("#mission-back-button").onclick=closeMissions;
$("#season-button").onclick=openSeason;
$("#season-back-button").onclick=closeSeason;
$("#upgrade-button").onclick=openUpgradeShop;
$("#upgrade-back-button").onclick=closeUpgradeShop;
$("#balance-button").onclick=openBalance;
$("#balance-back-button").onclick=closeBalance;
$("#pause-settings-button").onclick=()=>openSettings("pause");
$("#settings-back-button").onclick=closeSettings;
$("#ability-button").onclick=useAbility;
ui.pingButton.onclick=togglePingMenu;
ui.auxiliary.onclick=useAuxiliary;
ui.pingMenu.querySelectorAll("[data-ping]").forEach(button=>button.onclick=()=>issueTeamPing(button.dataset.ping));
$("#start-button").onclick=reset;
$("#play-again-button").onclick=returnToSelection;
$("#restart-button").onclick=reset;
$("#selection-button").onclick=returnToSelection;$("#pause-button").onclick=()=>pause(!state.paused);
$("#resume-button").onclick=()=>pause(false);
document.addEventListener("visibilitychange",()=>{if(document.hidden&&state.running&&!state.ended)pause(true)});
stick("#move-stick","move");stick("#aim-stick","aim");applyControlSettings();renderSettings();renderWallet();ui.best.textContent=formatBestTime(state.bestTime);resize();requestAnimationFrame(frame);
